# -*- coding: utf-8 -*-
# Pack W (ampliación): ¿de dónde sale el relato de Pablo en Ibn Kathir? Hadiz de Abu l-Darda', manuscritos y ediciones,
# iglesias de Damasco, y qué dicen otras fuentes musulmanas y los estudiosos.
SH = "shamela.ws (Maktaba Shamila; paginación igual a la edición impresa)"
S = "https://shamela.ws/book/"
USO = "Pack «Pablo en Damasco» (ampliación) · verificación de las fuentes"
IA = "archive.org (escaneo de la edición impresa; resaltado dibujado encima)"
WCARDS2 = [
 # ---------- A. El texto de Ibn Kathir y su orden ----------
 dict(id="W05", key="Ord", tag="Siglo VIII H · Ibn Kathir (m. 774 H / 1373)", specs=["X-ik118", "X-ik119"],
  title="El orden del texto original: primero el hadiz de Abu l-Darda' (doscientos años), luego Ibn Jarir/Ibn Ishaq y «varios»; el relato de Pablo viene después, sin cadena",
  ref="Ibn Kathir, al-Bidaya wa-l-nihaya (ed. ʿAli Shiri, Dar Ihya' al-Turath), vol. 2, pp. 118–119 (= Saʿada, vol. 2, p. 100)",
  ar_ref="البداية والنهاية ٢/١١٨–١١٩", site=SH, url=S + "8376/508 · 8376/509",
  es=["[[k:Y dijo Ibn Hibban en su Sahih: «Mención del tiempo que la comunidad de ʿIsa permaneció en su guía»]]: nos contó Abu…",
      "…Yaʿla, nos contó Abu Hammam, nos contó al-Walid ibn Muslim, de al-Haytham ibn Humayd, de al-Wadin ibn ʿAta', de Nasr ibn ʿAlqama, de Jubayr ibn Nufayr, de Abu l-Darda', que dijo: dijo el Mensajero de Dios ﷺ: «[[k:Dios se llevó a David de entre sus compañeros y no cayeron en la tentación ni cambiaron; y los compañeros del Mesías permanecieron en su sunna y su guía doscientos años]]». [[a:Y este hadiz es muy extraño (gharib jiddan), aunque lo autenticó Ibn Hibban.]] [[k:Y mencionó Ibn Jarir (2), de Muhammad ibn Ishaq]], que ʿIsa —la paz sea con él—, antes de ser elevado, encomendó a los discípulos que llamaran a la gente a adorar solo a Dios, sin asociado, y asignó a cada uno a un grupo de gente en una región de las regiones del Šam, el Oriente y el Magreb; y dicen que cada uno empezó a hablar la lengua de aquellos a quienes el Mesías lo envió. [[k:Y mencionaron varios (غير واحد)]] que el Evangelio lo transmitieron de él cuatro: Lucas, Mateo, Marcos y Juan; y entre estos cuatro evangelios hay mucha diferencia de un ejemplar a otro, y muchas adiciones y omisiones respecto del otro; y de estos cuatro, dos alcanzaron al Mesías y lo vieron —Mateo y Juan— y dos son de los compañeros de sus compañeros —Marcos y Lucas—. [[k:Y entre los de Damasco que creyeron en el Mesías y le dieron crédito]] había un hombre llamado Ḍīnā…",
      "(1) [[k:Lo transmitió al-Haytami en Mayma' al-zawa'id 8/207 y dijo: «Lo transmitió al-Tabarani y sus transmisores son fiables]], [[a:y en algunos de ellos hay discrepancia»]]. [Nota del editor de la edición Shiri.]"],
  prueba="El orden del original responde a la pregunta. El hadiz de Abu l-Darda' —Ibn Hibban lo pone bajo el título «cuánto tiempo la comunidad de ʿIsa siguió su guía»— no menciona a Pablo, ni Damasco, ni Ḍīnā: acaba en «doscientos años». Ibn Kathir da su valoración («muy extraño») y añade dos noticias con fuente propia (Ibn Jarir ← Ibn Ishaq; «varios»), y solo entonces empieza el relato de Pablo, sin cadena ni «dijo». Así que el relato no «bebe» del hadiz: va pegado a él, bajo el mismo tema (qué fue de los seguidores de Jesús tras su elevación). Su fuente real es la tradición de Wahb ibn Munabbih (W02).",
  ojo="Tres cautelas. (1) «Pegado» no es «desconectado»: la frase final sobre la fe «buena» de Pablo (W06) encaja con la idea del hadiz (los seguidores no cambiaron al principio). Es afinidad temática, no dependencia textual. (2) La puntuación es de los editores: en el texto sin puntuar, «وكان ممن آمن…» podría leerse como continuación de «y mencionaron varios»; nada lo impide. Lo que sabemos por otra vía (W02) es que el relato es de Wahb. (3) Sobre el hadiz: Ibn Kathir lo llama «muy extraño aunque lo autenticó Ibn Hibban». La nota del editor cita a al-Haytami (8/207, que no he leído en el original) con otra ruta (al-Tabarani) y «en algunos hay discrepancia». No he podido comprobar el veredicto de Ibn Hibban/Arna'ut ni de al-Albani: no uses el hadiz como «sahih» sin más.", uso=USO),

 dict(id="W06", key="D302", tag="Siglo VIII H · Ibn Kathir · edición crítica Dar Ibn Kathir (2010)", specs=["X-dar302"],
  title="La edición crítica de Dar Ibn Kathir (2010) trae el pasaje completo, con la variante «hasta que fue destruida en el tiempo que mencionaremos» y las notas «en B»",
  ref="Ibn Kathir, al-Bidaya wa-l-nihaya, ed. Dar Ibn Kathir (Damasco–Beirut), 2.ª ed. 1431/2010, tomo 1 (= partes 1–2), parte 2 (a cargo de ʿAli Abu Zayd), p. 302",
  ar_ref="البداية والنهاية، دار ابن كثير ٢/٣٠٢", site=IA, url="https://archive.org/details/2_20200225_20200225 (PDF p. 742)",
  es=["[…] entre sus compañeros y no cayeron en la tentación ni cambiaron, [[k:y los compañeros del Mesías permanecieron en su sunna y su guía doscientos años]]». [[a:Y este hadiz]] [[a:es muy extraño, aunque lo autenticó Ibn Hibban.]]",
      "Y mencionaron varios que el Evangelio lo transmitieron de él cuatro: Lucas, Mateo, Marcos y Juan, […] y de estos cuatro, dos alcanzaron al Mesías y lo vieron —Mateo y Juan— y dos son de los compañeros de sus compañeros —Marcos y Lucas—. Y entre los de Damasco que creyeron en el Mesías y le dieron crédito había un hombre llamado Ḍīnā, que estaba escondido en una cueva dentro de la Puerta Oriental, cerca de la Iglesia Muṣallaba, por miedo a Pablo el judío, que era injusto, opresor y odiaba al Mesías y lo que trajo. Había rapado la cabeza de su sobrino cuando creyó en el Mesías, lo paseó por la ciudad y luego lo apedreó hasta que murió —Dios tenga misericordia de él—. Y cuando Pablo oyó que el Mesías —la paz sea con él— se había dirigido hacia Damasco, [[a:preparó sus mulas (1)]] y salió a matarlo; lo encontró en Kawkaba (2), y cuando se enfrentó a los compañeros del Mesías, vino a él un ángel, le golpeó la cara con la punta de su ala y lo dejó ciego. Al ver eso, le entró en el alma creer en el Mesías; fue a él, se disculpó por lo que había hecho y creyó en él, y él lo aceptó; le pidió que le pasara la mano por los ojos para que Dios le devolviera la vista, y le dijo: «Ve a Ḍīnā, que está cerca de ti en Damasco, al extremo oriental del mercado largo, y él rezará por ti». Fue a él, rezó, y le devolvió la vista; [[k:y la fe de Pablo en el Mesías —la paz sea con él— se volvió buena: que es siervo de Dios y Su mensajero]], [[k:y se le construyó una iglesia con su nombre, que es la famosa iglesia de Pablo en Damasco, desde el tiempo en que la conquistaron los Compañeros —Dios esté complacido con ellos—]] [[k:hasta que fue destruida en el tiempo que mencionaremos (3), si Dios quiere]].",
      "(1) [[a:En B: «las tropas».]] (2) En Muʿyam al-buldan: «Kawkab: … nombre de una fortaleza en el monte que domina la ciudad de Tiberíades». (3) [[a:En B: «que mencionaremos más adelante».]]"],
  prueba="Leída sobre la imagen de la edición crítica (el escaneo no tiene texto digital): el pasaje de Pablo está completo y trae una cláusula que los textos de Shiri (2/119) y de Saʿada (2/101) no tienen: «hasta que fue destruida en el tiempo que mencionaremos, si Dios quiere». El manuscrito B (Berlín) da variantes en este mismo pasaje: «las tropas» en vez de «sus mulas», y «más adelante» en la última cláusula. Es decir: la «buena fe» de Pablo y su iglesia están en el texto de la edición crítica y en el manuscrito B, no solo en impresos antiguos.",
  ojo="(1) No he visto los manuscritos, solo la edición. (2) Esta página no anota ninguna laguna: contrasta con la nota de Saʿada (W08), según la cual dos copias egipcias no tienen el bloque. (3) «ب» es el manuscrito de Berlín, copista Muhammad ibn Sultan ibn Saʿid al-Baʿli al-Hanbali, y la edición dice que no halló la fecha de copia (W07): el «805 H» que te pasaron no sale de aquí. (4) La nota 2 no es una variante: es una glosa de Yaqut sobre Kawkab. (5) «Destruida en el tiempo que mencionaremos»: Ibn Kathir habla de una iglesia real, cuya ruina narra más adelante; es dato suyo, no de Wahb.", uso=USO),

 dict(id="W07", key="Dms", tag="Siglo XV H · edición crítica Dar Ibn Kathir (2010) · descripción de los manuscritos", specs=["X-dar85"], secondary=True,
  title="Los manuscritos de la edición crítica: A = al-Ahmadiyya de Alepo (completo hasta 738 H, sin copista ni fecha); B = Berlín (copista Ibn Sultan al-Baʿli al-Hanbali, «no hallamos la fecha de copia»)",
  ref="Ibn Kathir, al-Bidaya wa-l-nihaya, ed. Dar Ibn Kathir 2010, tomo 1, Introducción, «Descripción de los manuscritos», pp. 85–86",
  ar_ref="وصف النسخ المخطوطة ٨٥–٨٦", site=IA, url="https://archive.org/details/2_20200225_20200225 (PDF pp. 89–90)",
  es=["[…] Primero, la copia al-Ahmadiyya: [[k:se le asignó la letra «A», y es la copia al-Ahmadiyya de la ciudad de Alepo, n.º (1217)]], [[k:y hoy se conserva en la Biblioteca Nacional al-Asad de Damasco]] con el título «al-Bidaya wa-l-nihaya» del hafiz Ibn Kathir, y consta de diez partes.",
      "[…] [[k:La copia al-Ahmadiyya está completa hasta el año 738 H]] y corregida; los títulos y encabezados de párrafo se escribieron en rojo; la letra: naskh corriente, [[a:no hallamos el nombre del copista ni la fecha de copia]]. La cubierta está decorada; y en la primera página de la parte primera hay [[k:anotaciones de propiedad del año 874 H y del año]] [[k:923 H]], y anotaciones y lecturas sin fecha.",
      "[…] Segundo, la copia de Berlín: [[k:se le asignó la letra «B», y es una copia conservada en la Biblioteca Nacional de Berlín]], que empieza con una página con anotaciones de propiedad, y la segunda página lleva el título del libro así: «Parte primera de al-Bidaya wa-l-nihaya…»; […]",
      "[…] Es una copia que empieza por los comienzos de la parte primera y termina con las defunciones del año 738 H; en sus márgenes hay glosas; […] su letra es naskh antigua, (780) folios, de 20 × 13 cm, [[k:con 30 líneas por página; la copió Muhammad ibn Sultan ibn Saʿid al-Baʿli al-Hanbali —que Dios lo perdone con Su favor y generosidad—]] [[a:y no hallamos la fecha de copia]]."],
  prueba="Confirmado sobre las páginas impresas (leídas en la imagen): el manuscrito A de la edición es el de Alepo (al-Ahmadiyya, n.º 1217, hoy en la Biblioteca al-Asad, 10 partes), completo hasta 738 H, con notas de propiedad de 874 y 923 H; el B es de Berlín, copista Muhammad ibn Sultan ibn Saʿid al-Baʿli al-Hanbali, 780 folios, 30 líneas. Coincide con lo que decía el análisis.",
  ojo="Lo que el análisis añadía —«copia fechada en 805 H, según Rasmus Bech Olsen»— no está en esta edición: dice expresamente «no hallamos la fecha de copia». Mi agente de la tesis de Olsen (Birkbeck, 2017) no halló ese dato, y no he podido leerla entera. Tampoco puedo decir si este B es el ms. de Berlín descrito por Ahlwardt (W13), cuyo copista y fecha son otros. Y esta página no dice cuándo se copió A: las notas de 874 y 923 H solo dan un «a más tardar».", uso=USO),

 # ---------- B. Las ediciones: nota de Saʿada, Qisas, introducción ----------
 dict(id="W08", key="Sa100", tag="Siglo VIII H · Ibn Kathir · edición Saʿada (El Cairo, 1351 H / 1932)", specs=["X-sa100b", "X-sa100"],
  title="La nota [1] de Saʿada, p. 100: «desde aquí hasta [Libro de las noticias de los pasados] no se halló en las dos copias de la Biblioteca Egipcia; en su lugar, un poema de al-Qarafi»",
  ref="Ibn Kathir, al-Bidaya wa-l-nihaya (Matbaʿat al-Saʿada, El Cairo), vol. 2, p. 100 (= Shiri 2/119; Dar Hajar 2/529)",
  ar_ref="البداية والنهاية، ط. السعادة ٢/١٠٠", site=SH, url=S + "23708/438",
  es=["[…] ‹Y estos cuatro›: dos de ellos alcanzaron al Mesías y lo vieron —Mateo y Juan—, [[k:y dos de los compañeros de sus compañeros (1)]] —Marcos y Lucas—. [[k:Y entre los de Damasco que creyeron en el Mesías y le dieron crédito]] había un hombre llamado Ḍīnā, escondido en una cueva dentro de la Puerta Oriental, cerca de la Iglesia Muṣallaba, por miedo a Pablo el judío, que era injusto, opresor y odiaba al Mesías y lo que trajo. Y había rapado la cabeza de su sobrino cuando creyó en el Mesías…",
      "[…] Y cuando Pablo oyó que el Mesías se dirigía hacia Damasco, preparó sus mulas y salió a matarlo; lo encontró en Kawkaba, y cuando se enfrentó a los compañeros del Mesías vino a él un ángel, le golpeó la cara con la punta de su ala y lo dejó ciego. [[k:Y cuando vio eso, cayó…]] [fin de la p. 100] (1) [[k:Desde aquí hasta su frase «[Libro de las noticias de los pasados]», etc., no se halló en las dos copias que hay en la Biblioteca Egipcia]], [[a:y se halló en ellas, en su lugar, esta redacción:]] [[a:«Y entonó el šayj Šihab al-Din al-Qarafi en su libro La refutación de los cristianos»]], de alguien, refutándoles su doctrina de la crucifixión del Mesías y su entrega a los judíos mientras afirman que es hijo de Dios —¡exaltado sea Dios de lo que dicen!—: «¡Qué asombro del Mesías entre los cristianos… y a Dios atribuyeron un hijo! Lo entregaron a los judíos, y dijeron… que tras matarlo lo crucificaron. Si lo que decís es cierto y verdadero… ¿dónde estaba su padre cuando dejó a su hijo rehén de los enemigos? ¿Acaso lo complacieron o lo irritaron? Si estaba satisfecho de su daño… disculpadlos, pues estuvieron de acuerdo con él; y si estaba enfadado, abandonadlo… y adorad a los que lo vencieron.»"],
  prueba="Confirmado, y aclarado el alcance. El número (1) está pegado en «los compañeros de sus compañeros» (Marcos y Lucas), y la nota dice que desde ahí hasta «[Libro de las noticias de los pasados]» el texto no está en las dos copias de la Biblioteca Egipcia, que traen en su lugar un poema polémico de al-Qarafi (m. 684 H) contra la crucifixión. Es un bloque grande: contiene todo el relato de Ḍīnā/Pablo, el apartado sobre Constantino y el Credo (W09–W10), no solo las frases sobre la fe de Pablo.",
  ojo="Esto no demuestra que esas frases sean un añadido tardío: (1) lo que falta en las dos copias egipcias es un bloque entero, sustituido por una cita polémica; o su antepasado común estaba defectuoso o alguien cortó y puso la cita —no sabemos cuál—. (2) La edición crítica de 2010 (W06–W07) trae el pasaje con base en el ms. de Alepo y el de Berlín. (3) La propia Saʿada lo imprime porque su base era la copia de Alepo cotejada con la fotografía egipcia (W12). (4) Qué «dos copias» son esas no está dicho (W12). Una cosa más: este argumento de manuscritos es mío; los editores solo dicen «no se halló».", uso=USO),

 dict(id="W09", key="Sa101", tag="Siglo VIII H · Ibn Kathir · edición Saʿada, vol. 2, p. 101", specs=["X-sa101"],
  title="Pegado a la «buena fe» de Pablo, Ibn Kathir fecha «la gran calamidad y la desgracia mayor» trescientos años después del Mesías, con Constantino",
  ref="Ibn Kathir, al-Bidaya wa-l-nihaya (ed. Saʿada), vol. 2, p. 101 (= Shiri 2/119–120)",
  ar_ref="البداية والنهاية، ط. السعادة ٢/١٠١", site=SH, url=S + "23708/439",
  es=["[…] cayó en su alma creer en el Mesías; fue a él, se disculpó por lo que había hecho y creyó en él, y él lo aceptó; le pidió que le pasara la mano por los ojos para que Dios le devolviera la vista, y le dijo: «Ve a Ḍīnā, que está cerca de ti en Damasco, al extremo oriental del mercado largo, y él rezará por ti». Fue a él, rezó, y le devolvió la vista; [[k:y la fe de Pablo en el Mesías —la paz sea con él— se volvió buena: que es siervo de Dios y Su mensajero]], y se le construyó una iglesia con su nombre, que es la famosa iglesia de Pablo en Damasco, desde el tiempo en que la conquistaron los Compañeros hasta que fue destruida en el tiempo que mencionaremos, si Dios quiere. [Sección] Los compañeros del Mesías —la paz sea con él— discreparon tras su elevación al cielo sobre él en varias opiniones, como dijo Ibn ʿAbbas y otros imames de los antepasados, según lo hemos expuesto al comentar Su dicho «Y apoyamos a los que creyeron contra su enemigo y se volvieron vencedores» [Corán 61:14]. Dijo Ibn ʿAbbas y otros: unos dijeron «era siervo de Dios y Su mensajero, y fue elevado al cielo»; otros dijeron «es Dios»; otros, «es el hijo de Dios». Lo primero es la verdad, y las otras dos son una gran incredulidad (kufr), como dijo Dios: «Los partidos discreparon entre sí: ¡ay de los que no creen, por la presencia de un día terrible!». Y discrepaban en la transmisión de los evangelios en cuatro versiones, entre adición y omisión, alteración (taḥrīf) y cambio (tabdīl). [[k:Luego, trescientos años después del Mesías, ocurrió en él la gran calamidad y la desgracia mayor.]] Los cuatro patriarcas y todos los obispos, sacerdotes, diáconos y monjes discreparon sobre el Mesías en opiniones numerosas, incontables e inabarcables, [[k:y se reunieron y acudieron como árbitro al rey Constantino]], constructor de Constantinopla —y es el primer concilio—; y el rey se inclinó por la opinión de la mayor fracción, que se había puesto de acuerdo en una de aquellas opiniones; «y los llamaron los ángeles» [impreso: فسموا الملائكة; texto probablemente corrupto, quizá «los melquitas»] y se rechazó y apartó a los demás."],
  prueba="Es el centro del argumento. En el mismo apartado y a continuación de la buena fe de Pablo, Ibn Kathir (1) dice que los seguidores de Jesús discrepaban sobre quién es (siervo y mensajero / Dios / hijo de Dios), y que la primera opinión «es la verdad»; y (2) fecha «la gran calamidad y la desgracia mayor» trescientos años después del Mesías, con el concilio ante Constantino. Para Ibn Kathir, por tanto, el giro doctrinal no lo hace Pablo sino el concilio de Constantino (Nicea). Y su Pablo cree, según su relato, que Jesús «es siervo de Dios y Su mensajero».",
  ojo="Es lo que dice Ibn Kathir, no lo que dice la historia: no prueba que Pablo no enseñara una cristología alta (los cristianos, y muchos académicos, dicen que Pablo ya proclama a Cristo como Señor). Prueba solo que, dentro de la fuente islámica que se suele citar, la culpa no se atribuye a Pablo. Además: (a) en la transmisión de los evangelios habla de «adición, omisión, alteración y cambio» sin atribuírselo a Pablo; (b) el hadiz de Abu l-Darda' dice 200 años y aquí «300»: cifras distintas que no armoniza, y el hadiz es «muy extraño» (W05); (c) todo este bloque falta en las dos copias egipcias (W08); (d) otros musulmanes (Ibn Hazm, Sayf: W18–W22) sí culpan a Pablo.", uso=USO),

 dict(id="W10", key="Sa102", tag="Siglo VIII H · Ibn Kathir · edición Saʿada, vol. 2, p. 102", specs=["X-sa102"],
  title="Ibn Kathir copia el Credo y lo llama, con su propia voz, «en realidad la mayor incredulidad y traición»; ahí acaba lo que falta en las copias egipcias",
  ref="Ibn Kathir, al-Bidaya wa-l-nihaya (ed. Saʿada), vol. 2, p. 102",
  ar_ref="البداية والنهاية، ط. السعادة ٢/١٠٢", site=SH, url=S + "23708/440",
  es=["[…] sus mujeres y sus hombres, que llaman «la Amana» [el Credo], [[k:y que en realidad es la mayor incredulidad y traición]]. Y todos los melquitas y los nestorianos, partidarios de Nestorio —gente del segundo concilio—, y los jacobitas, partidarios de Jacobo Baradeo —gente del tercer concilio— creen este credo y discrepan en su interpretación. Y yo lo voy a relatar, [[a:y quien relata la incredulidad no es incrédulo]]; […]",
      "[…] una Iglesia única, [«كنسبة», impreso] universal, santa, [«يهولية», impreso, quizá «apostólica»]; y confieso un solo bautismo para el perdón de los pecados, y [espero] la resurrección de los muertos y la vida del siglo venidero. Amén. [[k:[Libro de las noticias de los pasados]]], de los hijos de Israel y otros, hasta el final del tiempo de la interrupción (fatra), salvo los días de los árabes y su yahiliyya, pues los relataremos [después de terminar esta sección, si Dios quiere]."],
  prueba="Aquí termina el bloque que la nota de W08 señala: la nota dice «hasta su frase [Libro de las noticias de los pasados]», que es el encabezado que se ve al final de esta página. Entre la fe de Pablo (W09) y ese encabezado solo están los apartados sobre los desacuerdos de los discípulos, Constantino y el Credo: lo mismo que Ibn Kathir presenta como el momento del cambio.",
  ojo="Ibn Kathir condena el credo trinitario: no es una cita neutral, y no hay que presentarla como aprobación de la doctrina cristiana. La tesis a tu favor es más modesta: que la fuente musulmana que se cita sobre Pablo no hace de Pablo el corruptor, sino que ve el cambio en los concilios. También hay erratas en el texto impreso del Credo («كنسبة», «يهولية»), señal de una transmisión descuidada de esta parte.", uso=USO),

 dict(id="W11", key="Qs", tag="Siglo VIII H · Ibn Kathir · Qisas al-anbiya' (ed. ʿAbd al-Wahid)", specs=["X-qs470"],
  title="En los «Relatos de los profetas» (extracto de la Bidaya) la copia A también se corta en «…vio eso, cayó…», y en su lugar trae el mismo poema de al-Qarafi",
  ref="Ibn Kathir, Qisas al-anbiya' (min al-Bidaya wa-l-nihaya), ed. ʿAbd al-Wahid (así en shamela: «ت. عبد الواحد»), vol. 2, p. 470",
  ar_ref="قصص الأنبياء ت. عبد الواحد ٢/٤٧٠", site=SH, url=S + "932/884",
  es=["Y mencionaron varios que el Evangelio lo transmitieron de él cuatro: Lucas, Mateo, Marcos y Juan, […] y entre los de Damasco que creyeron en el Mesías y le dieron crédito había un hombre llamado Ḍīnā, […] por miedo a Pablo el judío, que era injusto, opresor y odiaba al Mesías […]; y cuando Pablo oyó que el Mesías se dirigía hacia Damasco, preparó sus mulas y salió a matarlo; […] vino a él un ángel, le golpeó la cara con la punta de su ala y lo dejó ciego. «Y cuando vio eso, cayó» (1) [[k:Desde aquí hasta el final del libro falta en A.]] [[a:Y en la adición, este texto:]] [[a:«Y entonó el šayj Šihab al-Din al-Qarafi en su libro La refutación de los cristianos…»]] [sigue el mismo poema que en W08]"],
  prueba="El extracto «Relatos de los profetas» (sacado de la Bidaya) tiene el mismo fenómeno que la Saʿada: el manuscrito «A» de ese libro se corta en el mismo punto del relato de Pablo («Y cuando vio eso, cayó…») y añade el poema de al-Qarafi. Es decir, en dos obras y en dos ediciones el defecto es el mismo: una familia de copias con el pasaje ausente y el poema en su lugar.",
  ojo="Aquí la nota dice «hasta el final del libro» (el extracto termina ahí), y en W08 «hasta [Libro de las noticias…]»: los puntos de corte no coinciden al milímetro (aquí, justo en «cayó»). No sé si A de los «Relatos» es una de las copias egipcias de la nota de Saʿada ni de qué familia depende. Esto apunta a un defecto de la tradición manuscrita; no es prueba de una interpolación.", uso=USO),

 dict(id="W12", key="Sa3", tag="Siglo XIV H · Introducciones de las ediciones impresas", specs=["X-sa3", "X-hj35"], secondary=True,
  title="Saʿada (1932): «principal copia: la de Dar al-Kutub, fotografiada de Estambul, copiada en 1123 H»; Dar Hajar: Saʿada se basó en el ms. de Alepo, cotejado con la fotografía egipcia",
  ref="Ibn Kathir, al-Bidaya wa-l-nihaya, ed. Saʿada, vol. 1, p. 3 («Advertencia»); y ed. Dar Hajar (ʿAbd Allah al-Turki), 1417/1997, Introducción, p. 35",
  ar_ref="ط. السعادة ١/٣ ؛ ط. هجر، المقدمة ص ٣٥", site=SH + " · " + IA, url=S + "23708/3 · https://archive.org/details/bn21_20190727 (PDF p. 35)",
  es=["(Advertencia) Hemos impreso este libro ilustre [[k:tras cotejarlo con varios ejemplares]], y [[k:el principal es el gran ejemplar conservado en Dar al-Kutub al-Misriyya, tomado por fotografía de la biblioteca de Wali al-Din en la ciencia de Estambul]], cuya mayor parte está de puño y letra del docto šayj Mustafa Ahmad Hiyazi al-Muqri' (uno de los doctos de su época). Y escribió al final del primer tomo de ella lo siguiente […]: «y fue el sábado bendito, día quince del mes de Rayab del año [[k:1123 H]]».",
      "[Turki, introducción, sobre la primera edición impresa (Saʿada, 14 tomos):] [[k:«Se imprimió este tomo a partir del manuscrito conservado en la Escuela al-Ahmadiyya de la ciudad de Alepo (y en él nos hemos apoyado), tras cotejarlo con la copia fotográfica conservada en Dar al-Kutub al-Misriyya,]] y revisar el Mujtasar de la Sira de Ibn Ishaq de Ibn Hisham y su comentario al-Rawd al-Unuf de al-Suhayli, los Dalaʾil al-nubuwwa de al-hafiz Abu Nuʿaym, la Sira nabawiyya de Ibn Hisham y los diccionarios de la lengua»."],
  prueba="Las dos introducciones explican con qué manuscritos se hizo la Saʿada: la Advertencia de la propia Saʿada habla de «varios ejemplares», el principal el de Dar al-Kutub (fotografiado de Estambul, copiado en 1123 H); y la introducción de Dar Hajar —que cita el colofón de la Saʿada— dice que se imprimió «a partir del manuscrito de al-Ahmadiyya de Alepo (en el que nos hemos apoyado)», cotejado con la fotografía egipcia. Por eso la Saʿada imprime el pasaje que las dos copias egipcias no tienen (W08).",
  ojo="No sé si las «dos copias» de la nota de W08 son esta copia de 1123 H o otras. Una copia de 1123 H es unos 350 años posterior a Ibn Kathir (m. 774 H): no vale por sí sola para decidir qué escribió. La segunda captura es de la introducción de otra edición (Dar Hajar), que describe a la Saʿada de segunda mano; el colofón original de la Saʿada no lo he visto. La introducción de Dar Hajar no nombra manuscritos propios en las páginas leídas por mi agente (pp. 5–44).", uso=USO),

 dict(id="W13", key="Ahl", tag="Siglo XIX · catálogo de Berlín (Ahlwardt, 1893)", specs=["X-ahl"], secondary=True, lang="alemán (escaneo del catálogo impreso)",
  title="Un manuscrito de Berlín de al-Bidaya (Mf. 77, n.º 9455): copiado en 890 H (1485) por otro copista; colacionado en 960 H (1553)",
  ref="W. Ahlwardt, Verzeichniss der arabischen Handschriften der Königlichen Bibliothek zu Berlin, vol. 9 (Berlín, 1893), n.º 9455 (Mf. 77), p. 64",
  ar_ref="Ahlwardt IX, 63–64", site="archive.org (escaneo del catálogo; resaltado dibujado encima)", url="https://archive.org/details/diehandschriften21preu (p. 64)",
  trnote="Traducción propia del alemán. ",
  es=["[…] Escritura: desigual, en conjunto pequeña, apretada, mano de erudito, mayormente sin vocales, a menudo también sin puntos diacríticos. Los títulos, normalmente en rojo. Al foliar se saltaron los f. 127–135 y 197–198. Tras el f. 223 hay una hoja sin numerar, ahora 223A. — [[k:Copia de [nombre árabe; en la imagen parece «Naŷm al-Din al-Kutubi ibn Ahmad…»] en el año 890, Raŷab (1485)]]. — [[a:Colacionado por [nombre árabe] en el año 960/1553.]]"],
  prueba="Ahlwardt describe un manuscrito de la Bidaya (parte primera, «desde el principio del mundo hasta el Profeta») que se guarda en Berlín: copiado en 890 H (1485) y colacionado en 960 H (1553), con copista y colacionador que NO son Muhammad ibn Sultan.",
  ojo="Este escaneo sirve para algo negativo: la fecha de este manuscrito de Berlín no es 805 H ni el copista el de la edición crítica. Pero NO sé si el «B» de la edición de 2010 es este manuscrito: la edición dice 780 folios, 30 líneas, hasta 738 H, copista Ibn Sultan al-Baʿli, mientras que Ahlwardt describe un volumen de unos 230 folios con la parte primera. Puede ser otro volumen berlinés. La afirmación «805 H (Olsen)» sigue sin confirmar; lo que sí hay es una fecha berlinesa distinta (890 H).", uso=USO),

 # ---------- C. Iglesias de Damasco ----------
 dict(id="W14", key="Igl", tag="Siglo VIII H · Ibn Kathir, citando a Ibn ʿAsakir", specs=["X-ik581"],
  title="Ibn Kathir enumera las catorce iglesias que los Compañeros dejaron a los cristianos de Damasco: la quinta, «la iglesia de Pablo, al oeste de la Qaysariyya al-Fajriyya»",
  ref="Ibn Kathir, al-Bidaya wa-l-nihaya (ed. al-Turki, Dar Hajar), vol. 9, p. 581, «El pacto con la gente de Damasco»",
  ar_ref="البداية والنهاية ت. التركي ٩/٥٨١", site=SH, url=S + "4445/5454",
  es=["[…] [como] mezquita, y les dejaron la mitad occidental como iglesia. [[k:Y además les dejaron catorce iglesias más]], junto con la mitad de la iglesia conocida como de Yuhanna [Juan], que hoy es la mezquita de Damasco; y Jalid ibn al-Walid les escribió un documento sobre ello, y en él dieron testimonio Abu ʿUbayda, ʿAmr ibn al-ʿAs, Yazid y Šurahbil: la primera es la iglesia del Miqsallat, junto a la cual se reunieron los emires de los Compañeros; estaba construida sobre el lomo del gran zoco, y estos arcos que se ven en el zoco de los Sabuniyyin son restos de los arcos que había debajo; luego desapareció y sus piedras se usaron en edificios. La segunda: una iglesia que estaba al comienzo del Darb de los Qurašíes, y era pequeña. Dijo el hafiz Ibn ʿAsakir: parte de ella queda hasta hoy, pero está deteriorada. La tercera: estaba en Dar al-Battij al-ʿAtiqa. Dije: está dentro de la ciudad, cerca del Kushk; y creo que es la mezquita que hay frente al lugar mencionado, pues está en ruinas desde hace tiempo. Y Dios sabe más. La cuarta: estaba en el Darb de los Banu Nasr, entre el Darb de los Habbalin y el Darb al-Tamimi. Dijo el hafiz Ibn ʿAsakir: alcancé parte de su edificio, y la mayor parte está en ruinas. [[k:La quinta: la iglesia de Pablo. Dijo Ibn ʿAsakir: estaba al oeste de la Qaysariyya al-Fajriyya, y alcancé parte de su construcción, algo del cimiento del ábside]]. La sexta: estaba en el lugar de Dar al-Wakala, y hoy se conoce como iglesia de los Qalanisiyyin. Dije: los Qalanisiyyin son hoy los Jawwasin…"],
  prueba="Ibn Kathir conoce una «iglesia de Pablo» en Damasco por Ibn ʿAsakir: la lista de las catorce iglesias que los Compañeros dejaron tras el pacto, con su ubicación (al oeste de la Qaysariyya al-Fajriyya) y su estado (ya en ruinas, con restos del cimiento del ábside). Es la «famosa iglesia de Pablo» de la que habla al final del relato (W06, W09). Que la iglesia es real y está en Damasco no depende del relato de Wahb.",
  ojo="Dos matices. (1) Esta «iglesia de Pablo» (al oeste de la Qaysariyya) NO es la «Muṣallaba» del relato (junto a la Puerta Oriental): son dos iglesias distintas en la lista de Ibn ʿAsakir (W15). Ibn Kathir parece unir dos datos: el relato de Wahb y la lista. Es mi inferencia. (2) En los manuscritos de Ibn ʿAsakir la lectura de este nombre es dudosa (W15); y Ibn Kathir cita a Ibn ʿAsakir con «Pablo»: su ejemplar parece haberlo traído.", uso=USO),

 dict(id="W15", key="IAn", tag="Siglo VI H · Ibn ʿAsakir (m. 571 H / 1176) · lista de iglesias y aparato crítico", specs=["X-ia812", "X-ia813"],
  title="La lista de Ibn ʿAsakir: «la Muṣallaba sigue en pie entre la Puerta Oriental y Bab Tuma»; la «iglesia de Pablo» sale del impreso, no de los manuscritos",
  ref="Ibn ʿAsakir, Tarij madinat Dimashq (Dar al-Fikr, 1415/1995), vol. 2, pp. 356–357, «Capítulo sobre el número de iglesias de la gente del pacto» y notas del editor",
  ar_ref="تاريخ دمشق لابن عساكر ٢/٣٥٦–٣٥٧", site=SH, url=S + "71/812 · 71/813",
  es=["(2) [[k:Antes de ella, en el impreso: «iglesia de Pablo»; falta en el manuscrito base y en «خع»]]. [Nota al pie de la lista de iglesias.]",
      "[…] Y la iglesia de los judíos junto a al-Jayr sigue en pie, y tenían otra iglesia en el Darb al-Balagha, de la que no se hace mención en el libro del pacto, que fue convertida en mezquita. [[k:Y en cuanto a la iglesia de «Mariḍ» (1), estaba al oeste de la Qaysariyya al-Fajriyya (2); se arruinó, y alcancé parte de su construcción, algo del cimiento del ábside]].",
      "[…] Asid ibn Abi l-ʿAs y el Darb de Talha ibn ʿAmr ibn Murra al-Juhani (7). [[k:Y en cuanto a la iglesia Muṣallaba, sigue en pie para ellos hasta hoy, entre Bab al-Sharqi y Bab Tuma]], junto al Fustus (8), cerca de la muralla, y la mayor parte está en ruinas, [[a:y después fue demolida después de los ochenta (9).]]",
      "(1) [[a:Así en el manuscrito base; y en «خع»: «Bariṣ»]], [[k:y es la iglesia de Pablo, como en el impreso, y ya había caído antes de los dos manuscritos]], y la señalamos en su lugar.",
      "(9) Así; y esta frase [[k:parece ser un añadido de los copistas]], [[a:porque Ibn ʿAsakir murió antes de esa fecha.]]"],
  prueba="El aparato crítico confirma que la «iglesia de Pablo» de Ibn ʿAsakir depende del impreso antiguo: los manuscritos no la traen o la traen deformada («Mariḍ»/«Bariṣ»), y el editor la identifica con la de Pablo. Y la «Muṣallaba» —junto a la Puerta Oriental, «entre Bab Sharqi y Bab Tuma», donde el relato de Wahb sitúa la cueva de Ḥanīnā— figura aparte en la lista como iglesia que seguía en pie en tiempos de Ibn ʿAsakir. Es decir: el decorado del relato (Puerta Oriental, iglesia Muṣallaba) coincide con la topografía cristiana de Damasco que Ibn ʿAsakir mismo documenta.",
  ojo="(1) El editor equipara las lecturas dudosas («Mariḍ», «Bariṣ») con «Pablo» a partir del impreso: es una conjetura razonable, no una lectura segura. (2) La ubicación «al oeste de la Qaysariyya al-Fajriyya» también sale del impreso (nota 2: los manuscritos dicen otra cosa, «la Fisawiyya al-Bahriyya»). (3) «Demolida después de los ochenta» es, por la propia nota 9, un añadido de copistas. (4) Que el decorado sea topografía real no prueba por sí solo la tesis de Monferrer (W16: relato de origen cristiano damasceno), pero es coherente con ella. (5) No sé qué es «خع» (otro manuscrito de la edición): la edición debe definir la sigla.", uso=USO),

 dict(id="W16", key="Mon", tag="Siglo XX · estudio académico (Granada, 1996)", specs=["X-mon"], secondary=True, lang="español (resumen del artículo; API de CORE)",
  title="Monferrer Sala: el relato de la conversión de Saulo, «con interpolaciones, glosas y omisiones de clara procedencia musulmana», debía correr entre la comunidad cristiana de Damasco",
  ref="Juan Pedro Monferrer Sala, «La conversión de Saulo, según Ibn Katir», Miscelánea de Estudios Árabes y Hebraicos 45 (1996), pp. 147–159; resumen vía CORE (core.ac.uk)",
  ar_ref="Monferrer Sala 1996", site="core.ac.uk (resumen del artículo; no el PDF completo)", url="https://core.ac.uk/download/17310696.pdf",
  trnote="Reformulación propia, en lenguaje llano; el resumen está en español. ",
  es=["En otras palabras: Monferrer ve en el relato de la conversión de Pablo que cuenta Ibn Kathir un texto de estilo evangélico («la técnica de los evangelistas»), [[k:es decir, un relato que ya circulaba entre los cristianos de Damasco]]; [[a:los musulmanes lo retocaron con interpolaciones, glosas y omisiones]] «de clara procedencia musulmana», y así lo recogió Ibn Kathir."],
  prueba="Un especialista en literatura árabe cristiana y en Ibn Kathir llega, por el estilo del relato, a la misma conclusión que se ve en los textos (W02, W14–W15): la base del relato es la historia cristiana de Damasco (Hechos 9), reelaborada por musulmanes. Y las partes «de clara procedencia musulmana» serían precisamente los retoques.",
  ojo="Solo he leído el resumen: el PDF completo no estaba accesible (los servidores de la Universidad de Granada no respondían y CORE bloquea la descarga). El análisis que te pasaron decía que en la p. 156 la frase «Jesús es siervo de Dios y Su mensajero» es una «interpolación» musulmana: eso NO lo he podido comprobar. El estudio parte del texto de los «Qisas al-anbiya'», no solo de la Bidaya. Y «debía ser» es una hipótesis del autor («lo que nos lleva a pensar»), no un dato.", uso=USO),

 # ---------- D. Otras fuentes musulmanas sobre Pablo ----------
 dict(id="W17", key="Tab", tag="Siglo III H · al-Tabari (m. 310 H / 923)", specs=["X-tb600"],
  title="al-Tabari: Pablo «era de los seguidores y no era de los discípulos»; va con Pedro a Roma. Sin juicio moral",
  ref="al-Tabari, Tarij al-rusul wa-l-muluk, ed. Muhammad Abu l-Fadl Ibrahim (Dar al-Maʿarif, 2.ª ed. 1967), vol. 1, p. 603",
  ar_ref="تاريخ الطبري ١/٦٠٣", site=SH, url=S + "9783/600",
  es=["[…] y entre los que fueron enviados de los discípulos y de los seguidores que había en la tierra después de ellos: [[k:Pedro el discípulo, y con él Pablo —que era de los seguidores y no era de los discípulos—]], a Roma, […]"],
  prueba="al-Tabari (que no cuenta la historia de Ḍīnā/Ḥanīnā: V4) menciona a Pablo como un seguidor enviado a Roma con Pedro, sin ningún reproche. Según mi agente V4, en la sección del año 14 H sobre Damasco (la que cita el análisis) no hay ninguna iglesia, ningún Ḥanīnā y ningún Pablo.",
  ojo="La frase aleja a Pablo de los doce («no era de los discípulos»), que es lo que dice también la tradición cristiana (Pablo se presenta como «apóstol» a su modo, no como uno de los Doce). Y la sección de Tabari es un relato de origen cristiano resumido por él; no es su opinión sobre Pablo.", uso=USO),

 dict(id="W18", key="IH1", tag="Siglo V H · Ibn Hazm (m. 456 H / 1064)", specs=["X-ih156"],
  title="Ibn Hazm (negativo): «los rabinos sobornaron a Pablo el benjaminita —¡Dios lo maldiga!— y le ordenaron extraviar a sus seguidores»; y lo sabe «por lo que oímos de sus sabios»",
  ref="Ibn Hazm, al-Fisal fi l-milal wa-l-ahwaʾ wa-l-nihal, vol. 1, p. 164 (shamela libro 6521)",
  ar_ref="الفصل في الملل والأهواء والنحل ١/١٦٤", site=SH, url=S + "6521/156",
  es=["[…] [[k:Se pusieron de acuerdo en sobornar a Pablo el benjaminita —¡Dios lo maldiga!—]] y le ordenaron manifestar la religión de ʿIsa, la paz sea con él, [[k:y extraviar a sus seguidores]] y meterlos en la creencia de su divinidad; y le dijeron: [[k:«nosotros cargamos con tu pecado en esto»]], y lo hizo."],
  prueba="Es la fuente musulmana más dura contra Pablo, y hay que presentarla: Ibn Hazm lo llama «el maldito», lo hace un agente sobornado por los rabinos para introducir la divinidad de Jesús. Pero en el texto (justo antes de la parte capturada) lo atribuye a los judíos: «y por lo que oímos que mencionan sus sabios, sin negarlo, el sentido es que sus rabinos… se pusieron de acuerdo en sobornar a Pablo». Es decir, la tesis del «Pablo infiltrado» llega a Ibn Hazm por vía judía, no por revelación ni hadiz.",
  ojo="No es neutral a favor tuyo: Ibn Hazm SÍ acusa a Pablo (y lo da por bueno como argumento polémico). Y el pasaje impreso lleva la frase dos veces seguidas (es un defecto de la edición; el resaltado va sobre la segunda). Lo que muestra es que dentro del islam hay una tradición explícitamente anti-Pablo; no que no la haya. Y su origen declarado (los judíos) es un punto para la crítica de la fuente, no una refutación de lo que dice.", uso=USO),

 dict(id="W19", key="IH2", tag="Siglo V H · Ibn Hazm (m. 456 H / 1064)", specs=["X-ih217", "X-ih218", "X-ih219"],
  title="Ibn Hazm contra Pablo: carta a los gálatas «contradictoria», «este canalla… al que los judíos infiltraron», milagros «mentiras fabricadas»",
  ref="Ibn Hazm, al-Fisal fi l-milal wa-l-ahwaʾ wa-l-nihal, vol. 2, pp. 60–62 (shamela libro 6521)",
  ar_ref="الفصل ٢/٦٠–٦٢", site=SH, url=S + "6521/217 · /218 · /219",
  es=["[…] Y dijo [[k:Pablo el maldito]] en una de sus cartas, la dirigida a los gálatas, en el capítulo sexto [sic, según Ibn Hazm]: «Atestiguamos a todo hombre que se circuncida que está obligado a guardar todas las leyes de la Torá». Y dijo también antes: [[k:«Si os circuncidáis, el Mesías no os aprovechará»]]. ¡Admiraos de esto!",
      "Dijo Abu Muhammad [Ibn Hazm]: ¿Hay, para mostrar la desvergüenza de [[k:este canalla]] y su burla de quienes lo siguieron, y para confirmar [[k:lo que afirman los judíos: que sus antepasados infiltraron a este vil de Pablo]] [[k:para extraviar a los seguidores del Mesías]] —la paz sea con él— […] más que esta afirmación suya sobre la abrogación de los versículos y las normas…",
      "[…] y sus mentes no son sino como las de quien da crédito al ave fénix y a todo lo imposible. Y sabed que todo lo que atribuyen a Pedro, Juan, Marcos y Pablo en cuanto a milagros [[k:son mentiras fabricadas]], porque estos cuatro no fueron de [los de] la elevación del Mesías [sentido dudoso]; y [[k:desde que Pablo se hizo cristiano no fue sino perseguido, errante]], golpeado, [[k:como los zindiqs, oculto]]; y el propio Pablo cuenta de sí mismo que los judíos lo golpearon…"],
  prueba="Tres movimientos de Ibn Hazm: (1) cita a Pablo (Gálatas 5:2–3) para sostener que se contradice; (2) llama «vil» y «canalla» a Pablo y recoge «lo que dicen los judíos» de que fue infiltrado por sus antepasados; (3) niega sus milagros y lo describe, tras hacerse cristiano, como un fugitivo. Es la fuente a citar para ser honesto: la tradición anti-Pablo existe, con nombres y argumentos.",
  ojo="Ojo con lo que sí y no prueba: es la opinión de un polemista andalusí del siglo XI, con un argumento de texto (Gálatas) que merece respuesta exegética propia, no solo genealógica. Y fíjate en que Ibn Hazm cuenta a Pablo perseguido y errante («desde que se hizo cristiano»), lo que no encaja con la idea de un agente cómodo de un poder. Y su ‘fuente’ (los judíos) es la misma que señalan Folks y Whittingham (W21–W22) como origen de esta teoría.", uso=USO),

 # ---------- E. La investigación académica ----------
 dict(id="W20", key="FkA", tag="Siglo XXI · tesis doctoral (SBTS, 2024)", specs=["X-fk84", "X-fk85", "X-fk86"], secondary=True, lang="inglés (páginas del PDF)",
  title="Folks: en Ibn ʿAsakir, Pablo no es el corruptor: «carece de acusaciones de corrupción», aunque sí «se opuso al mensaje de Jesús»",
  ref="Shane Orin Folks, A Critique of the Early Islamic Charge That Paul Corrupted Christ's Original Religion (tesis doctoral, Southern Baptist Theological Seminary, 2024), pp. 84–86",
  ar_ref="Folks 2024, pp. 84–86", site="repository.sbts.edu (PDF de acceso abierto)", url="https://repository.sbts.edu/bitstreams/438fd777-1c8e-4b77-ba4d-8bd9d37854e4/download",
  trnote="Traducción propia del inglés. ",
  es=["Pablo aparece en la obra por su supuesta conversión en el camino a Damasco, [[k:y Ibn ʿAsakir atribuye el relato a Wahb ibn Munabbih]] (m. c. 725).",
      "La descripción que hace Ibn ʿAsakir de Pablo es breve y [[k:parece un relato de la conversión sobrenatural de Pablo (Hechos 9:1–19)]]. Escribe que Pablo era un jefe de los judíos, pero [[k:no incluye ningún detalle sobre Pablo persiguiendo cristianos]] (cf. Hechos 7:58; Gál 1:14).",
      "[…] En el relato de Ibn ʿAsakir, [[k:no afirma que Pablo corrompiera la religión de Jesús]], [[a:pero sí afirma que Pablo se opuso al mensaje de Jesús.]]",
      "La diferencia más llamativa entre Ibn ʿAsakir y otros escritores musulmanes es que el relato del encuentro con Jesús no sale de la boca de Pablo. Ibn ʿAsakir es el único autor que he examinado que [[k:incluye el encuentro en su relato de la biografía de Pablo, no en un relato de supuesta corrupción]].",
      "El relato de Ibn ʿAsakir es, por tanto, solo [[a:una indicación de lo que un musulmán medieval sabía de Pablo]], pero [[k:carece de acusaciones de corrupción]]."],
  prueba="Un estudio académico (cristiano, de un seminario bautista, y por eso de parte) lee el relato de Wahb en Ibn ʿAsakir como una versión de Hechos 9 sin el cargo de «corrupción»: la anécdota está en la biografía de Pablo, no en una acusación. Es la base académica del argumento de W02–W04: en la versión de Wahb que recoge Ibn ʿAsakir (y en la de al-Yaʿqubi, W01) la escena de Damasco aparece sin el cargo de «corrupción».",
  ojo="Folks no dice que Pablo salga bien parado: dice que Ibn ʿAsakir lo presenta primero como un enemigo de Jesús (azul). Y es una tesis doctoral de un autor cristiano: sirve de apoyo, no de árbitro. Sus páginas 84–86 resumen la entrada de Ibn ʿAsakir que ya hemos capturado en W02 (página original), que es lo que hay que citar como prueba.", uso=USO),

 dict(id="W21", key="FkB", tag="Siglo XXI · tesis doctoral (SBTS, 2024)", specs=["X-fk31"], secondary=True, lang="inglés (páginas del PDF)",
  title="Folks, p. 31: el «Pablo conspirador» aparece en el Toledot Yeshu judío, y Sayf (siglo VIII) pudo conocer pasajes de Lucas o Hechos",
  ref="Shane Orin Folks, A Critique of the Early Islamic Charge That Paul Corrupted Christ's Original Religion (SBTS, 2024), p. 31 y nota 33",
  ar_ref="Folks 2024, p. 31", site="repository.sbts.edu (PDF de acceso abierto)", url="https://repository.sbts.edu/bitstreams/438fd777-1c8e-4b77-ba4d-8bd9d37854e4/download",
  trnote="Traducción propia del inglés. ",
  es=["[Nota 33, sobre el Toledot Yeshu:] En este texto, [[k:a los judíos no les gusta que los cristianos profanen su sábado y sus fiestas.]] Persuaden a Elías, que se llama a sí mismo «Pablo», [[k:para ganarse la confianza de los cristianos y convencerlos de corromper su religión.]]",
      "La versión de Sayf del supuesto encuentro de Pablo con Jesús indica que Sayf [[a:quizá tuvo acceso a una copia de la Biblia, o al menos a partes de ella.]] Sean Anthony señala que [[a:todas las alusiones al Nuevo Testamento de Sayf proceden de Lucas o de Hechos.]]"],
  prueba="Lo que dice Folks (apoyado en Sean Anthony): el motivo del «Pablo conspirador» está en un texto judío, el Toledot Yeshu, donde los judíos instalan a un «Pablo» entre los cristianos para llevarlos a la corrupción. Y el relato de Sayf (siglo VIII), la primera acusación musulmana que lo cuenta, tiene huellas de Lucas/Hechos.",
  ojo="Es de segunda mano (no he leído el artículo de Anthony) y con fecha dudosa: el Toledot Yeshu es una obra judía de datación discutida, y que dos textos compartan un motivo no prueba que uno dependa del otro. Y de Ibn Hazm (W18) sabemos que él mismo dice que lo oyó de los judíos: eso sí apunta en esa dirección.", uso=USO),

 dict(id="W22", key="Wh", tag="Siglo XXI · artículo académico (Forum, 2025)", specs=["X-wh10", "X-wh11"], secondary=True, lang="inglés (páginas del PDF)",
  title="Whittingham (Oxford): Pablo no se nombra en el Corán ni en el hadiz; la teoría del «Pablo conspirador» arranca en Sayf y «se originó fuera del islam»; y hay también miradas más positivas",
  ref="Martin Whittingham, «A New (and Old) Muslim Approach to the Apostle Paul: Shabbir Akhtar on Paul's Letter to the Galatians», Forum Islamic-Theological Studies 4/2 (2025), pp. 10–11",
  ar_ref="Whittingham 2025, pp. 10–11", site="forum-journal.uibk.ac.at (PDF de acceso abierto)", url="https://forum-journal.uibk.ac.at/forum/article/download/143/14/384",
  trnote="Traducción propia del inglés. ",
  es=["Como mostrará un recorrido cronológico y geográfico por los escritos musulmanes, [[a:Pablo es considerado ampliamente la figura central en la distorsión de las enseñanzas originales de Jesús]], enseñanzas que se entienden acordes con el islam. [[k:Con todo, también aparece de vez en cuando un atisbo de una visión más positiva.]]",
      "A pesar de la importancia de Pablo en las visiones musulmanas históricas de la creencia y la escritura cristianas, [[k:no hay ninguna referencia explícita a él ni en el Corán ni en la literatura del hadiz.]]",
      "Así que el papel de Pablo empieza de formas muy modestas e insignificantes. Sin embargo, hay un relato temprano del poco conocido Sayf ibn ʿUmar que ofrece un cuadro muy distinto. [[a:Sayf (m. c. 180–193/796–809) retrata a Pablo no solo como equivocado, sino como un engañador deliberado]] (Sayf ibn ʿUmar, 1995; Anthony, 2008).",
      "Hay razones para creer que [[k:esta teoría del Pablo conspirador se originó fuera del islam, en la obra judía anónima Toledot Yeshu]] (2014). Así como los judíos convertidos al islam trajeron consigo su familiaridad con relatos de su propia comunidad, [[k:así esos relatos entraron en la nueva comunidad de los musulmanes]] (Whittingham, 2021, 142–48).",
      "El crítico musulmán de la Biblia más famoso, y famosamente duro, de los primeros siglos del islam es Ibn Ḥazm (m. 456/1064), […] Hace diversas críticas a Pablo, [[a:agrupándolo entre «la gente más tramposa de la creación»]] (Ibn Ḥazm, 2007, 253), condenándolo por prohibir la circuncisión (270), llamándolo «maldito», y afirmando que los relatos de milagros suyos son mentiras (327)."],
  prueba="Un especialista de Oxford ofrece, en una revista revisada por pares, el mapa honesto: (1) Pablo NO se nombra en el Corán ni en el hadiz; (2) la imagen del Pablo corruptor «domina» los escritos musulmanes (Sayf, Ibn Hazm…), pero con «destellos» positivos; (3) hay «razones para creer» que la teoría del «Pablo conspirador» nació en un texto judío y entró en el islam con judíos conversos. Esto sostiene tres cosas: la acusación no es revelada; la tradición musulmana sobre Pablo no es unánime; y el relato de Ibn Kathir es una excepción dentro de ella.",
  ojo="Whittingham también dice lo contrario de lo que querrías: «Pablo es ampliamente considerado la figura central en la distorsión de las enseñanzas de Jesús». Es la misma página (en azul). No presentes a los musulmanes como si consideraran inocente a Pablo: lo que se sostiene es que dentro de las fuentes islámicas hay textos (Ibn Kathir) que no lo hacen corruptor, y que la acusación tiene un origen extra-coránico. «Hay razones para creer» es una hipótesis, no un hecho cerrado.", uso=USO),
]
